void test_div(my_decimal decimal1, my_decimal decimal2, my_decimal check) {
  my_decimal result;
  int code = my_div(decimal1, decimal2, &result);
#if defined(__DEBUG)
  printf("---------------------------------\n");
  printf("\n\nTests:\n");
  my_print_decimal_bits(decimal1);
  my_print_decimal_string(decimal1);
  my_print_decimal_bits(decimal2);
  my_print_decimal_string(decimal2);
  printf("\ncheck:\n");
  my_print_decimal_bits(check);
  my_print_decimal_string(check);
  printf("\nres:\n");
  my_print_decimal_bits(result);
  my_print_decimal_string(result);
  printf("---------------------------------\n");
#endif
  ck_assert_int_eq(my_is_equal(result, check), 1);
  ck_assert_int_eq(code, TEST_ARITHMETIC_OK);
}

void test_div_fail1(my_decimal decimal1, my_decimal decimal2,
                    int code_check) {
  my_decimal result;
  int code = my_div(decimal1, decimal2, &result);

#if defined(__DEBUG)
  printf("---------------------------------\n");
  printf("\n\nTests:\n");
  my_print_decimal_bits(decimal1);
  my_print_decimal_string(decimal1);
  my_print_decimal_bits(decimal2);
  my_print_decimal_string(decimal2);
  printf("\ncheck:\n");
  my_print_decimal_bits(result);
  my_print_decimal_string(result);
  printf("\nres:\n");
  my_print_decimal_bits(result);
  my_print_decimal_string(result);
  printf("Check: %d\n", code_check);
  printf("Result: %d\n", code);
  printf("---------------------------------\n");
#endif

  ck_assert_int_eq(code, code_check);
}

